                    pa_array.type
                ):
                    # TODO: Move logic in _from_sequence_of_strings into
                    # _box_pa_array
                    dtype = ArrowDtype(pa_type)
                    return cls._from_sequence_of_strings(
                        value, dtype=dtype
                    )._pa_array
                else:
                    raise

    return pa_array

